    /// Normalizes an app title or bundle ID into a candidate Simple Icons slug.
    public static func normalizeSlug(_ input: String) -> String {
        var clean = input.lowercased()
        if clean.hasSuffix(".app") { clean.removeLast(4) }
        if clean.contains(".") {
            if let last = clean.split(separator: ".").last {
                clean = String(last)
            }
        }
        // Known common aliases
        switch clean {
        case "code", "vscode": return "visualstudiocode"
        case "chrome": return "googlechrome"
        case "tg": return "telegram"
        case "vlc": return "vlcmediaplayer"
        case "sublime", "sublime-text": return "sublimetext"
        case "iterm": return "iterm2"
        case "twitter": return "x"
        case "photoshop": return "adobephotoshop"
        case "illustrator": return "adobeillustrator"
        case "premiere", "premierepro": return "adobepremierepro"
        case "idea", "intellij": return "intellijidea"
        case "nvim": return "neovim"
        case "tor": return "torbrowser"
        case "cleanmymacx": return "cleanmymac"
        case "golang": return "go"
        default: break
        }
        return clean.filter { $0.isLetter || $0.isNumber }
    }

    /// Looks up a curated Simple Icon by exact app title, alias, or slug.
    public static func find(for appTitle: String) -> SimpleIcon? {
        let targetSlug = normalizeSlug(appTitle)
        if let exact = curated.first(where: { $0.slug == targetSlug }) {
            return exact
        }
        let lowerTitle = appTitle.lowercased()
        return curated.first { lowerTitle.contains($0.slug) || lowerTitle.contains($0.title.lowercased()) }
    }

    /// Filters curated icons by a search query (matches title or slug).
    public static func search(query: String) -> [SimpleIcon] {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return curated }
        return curated.filter {
            $0.title.lowercased().contains(q) || $0.slug.contains(q)
        }
    }

    /// The remote jsDelivr CDN URL for any official Simple Icon slug.
    public static func remoteURL(for slug: String) -> URL? {
        let clean = slug.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !clean.isEmpty else { return nil }
        return URL(string: "https://cdn.jsdelivr.net/npm/simple-icons/icons/\(clean).svg")
    }

    private static let cacheDirectory: URL = {
        let appSupport = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first
            ?? URL(fileURLWithPath: NSTemporaryDirectory())
        let dir = appSupport.appendingPathComponent("Modo/SimpleIconsCache", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }()

    /// Searches locally first, then attempts to fetch official SVG from CDN and caches to disk.
    public static func fetch(slugOrTitle: String) async -> SimpleIcon? {
        if let local = find(for: slugOrTitle) {
            return local
        }
        let slug = normalizeSlug(slugOrTitle)
        guard !slug.isEmpty else { return nil }

        // Check local disk cache
        let cachedFile = cacheDirectory.appendingPathComponent("\(slug).svg")
        if let data = try? Data(contentsOf: cachedFile), let svgText = String(data: data, encoding: .utf8) {
            return SimpleIcon(
                title: slug.capitalized,
                slug: slug,
                hex: 0x111111,
                path: "",
                rawSVG: svgText
            )
        }

        // Fetch from jsDelivr CDN
        guard let url = remoteURL(for: slug) else { return nil }
        var req = URLRequest(url: url)
        req.timeoutInterval = 6.0
        guard let (data, resp) = try? await URLSession.shared.data(for: req),
              let http = resp as? HTTPURLResponse, http.statusCode == 200,
              let svgText = String(data: data, encoding: .utf8), !svgText.isEmpty else {
            return nil
        }

        // Cache on disk for instant offline access next time
        try? data.write(to: cachedFile, options: .atomic)

        return SimpleIcon(
            title: slug.capitalized,
            slug: slug,
            hex: 0x111111,
            path: "",
            rawSVG: svgText
        )
    }
}
